import React, { useState } from 'react';
import TaskCard from './TaskCard';

const TaskList = ({ tasks, onUpdate, onDelete, onEdit }) => {
  const [filter, setFilter] = useState('All'); // All, Pending, Completed

  // Filter tasks based on selected filter
  const filteredTasks = tasks.filter((task) => {
    if (filter === 'All') return true;
    return task.status === filter;
  });

  return (
    <div className="task-list-section">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h4 className="m-0">Your Tasks</h4>

        {/* Filters */}
        <div className="task-filters btn-group" role="group">
          {['All', 'Pending', 'Completed'].map((f) => (
            <button
              key={f}
              type="button"
              className={`btn btn-sm ${filter === f ? 'btn-primary active-filter' : 'btn-outline-secondary'}`}
              onClick={() => setFilter(f)}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      {filteredTasks.length === 0 ? (
        <div className="empty-state">
          <div className="empty-icon">
            <i className="bi bi-clipboard-x"></i>
          </div>
          <h5>No tasks found</h5>
          <p className="text-muted">
            {filter === 'All' 
              ? "You don't have any tasks yet. Add one above to get started!"
              : `You don't have any ${filter.toLowerCase()} tasks.`}
          </p>
        </div>
      ) : (
        <div className="task-grid">
          {filteredTasks.map((task) => (
            <TaskCard
              key={task._id}
              task={task}
              onUpdate={onUpdate}
              onDelete={onDelete}
              onEdit={onEdit}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default TaskList;
